package scan

import (
	"os/exec"
	"strings"
	"unicode"
)

// shellMeta are the characters that make a shell read more than words in a
// command: separators, expansions, redirections, quoting, globbing, comments.
const shellMeta = ";|&$`<>()\\'\"{}*?!#"

// PlainWords reports whether cmd is made of visible characters and single
// spaces, with no shell metacharacter. It is the one computation behind every
// command DevDesk offers to copy (DEVDESK-751, DEVDESK-752): the Run line of the
// finding detail, and a Repro line built here or read back from a cache.
func PlainWords(cmd string) bool {
	for _, r := range cmd {
		switch {
		case r == ' ':
		case unicode.IsControl(r), !unicode.IsPrint(r), strings.ContainsRune(shellMeta, r):
			return false
		}
	}
	return true
}

// lookPath is the seam of the program name: whether the tool a scan ran is the
// one `name` resolves to on PATH. TestMain replaces it, so no test depends on
// the helm or the kustomize of the machine it runs on.
var lookPath = exec.LookPath

// reproLine joins a program and its arguments into one line, or refuses.
//
// SKELETON (DEVDESK-752, red phase): returns no line until the coder writes it.
// It must refuse the whole line when a token is empty, holds a blank, or is not
// PlainWords: a path with a space gives no Repro rather than a command that
// splits it.
func reproLine(program string, args ...string) (string, bool) {
	_, _ = program, args
	return "", false
}

// reproProgram is the name to show for a program: the plain tool name when
// lookPath finds the same binary, else the configured path.
//
// SKELETON (DEVDESK-752, red phase).
func reproProgram(binary, name string, look func(string) (string, error)) string {
	_, _, _ = binary, name, look
	return ""
}

// localRepro is the Repro line of a finding one tool command could reproduce,
// and where the tool ran. A tool in a container gives no line and says so by its
// source; a line that cannot be written plainly gives none either.
//
// SKELETON (DEVDESK-752, red phase).
func localRepro(tool ToolSpec, name string, args ...string) (repro string, from ToolSource) {
	_, _, _ = tool, name, args
	return "", ""
}
package scan

// The numbered steps DevDesk writes for the findings it builds itself
// (DEVDESK-752). Every function here is pure: the caller says what it ran and
// what the tool printed.
//
// SKELETON (DEVDESK-752, red phase): every writer returns nil until the coder
// writes it. The signatures are the contract the tests pin.

// renderSteps are the steps for a chart or an overlay that did not render.
// target is the overlay directory or the chart, relative to the scanned
// directory; detail is what the tool printed.
func renderSteps(source, target string, from ToolSource, detail string) []string {
	_, _, _, _ = source, target, from, detail
	return nil
}

// helmLintSteps are the steps for one message of helm lint: file is the finding's
// file and chart the chart directory.
func helmLintSteps(file, chart string) []string {
	_, _ = file, chart
	return nil
}

// schemaSteps are the steps for a field the schema rejected. rendered is "" for
// a plain manifest and the renderer's dialect (helm, kustomize) for a rendered
// one.
func schemaSteps(r kubeconformResource, p kubeconformFieldProblem, version, rendered string) []string {
	_, _, _, _ = r, p, version, rendered
	return nil
}

// secretSteps are the steps for a secret Gitleaks or Trivy found. It returns a
// new slice on every call: a shared one would let a caller change every finding.
func secretSteps() []string { return nil }
package security

import (
	"github.com/anthnel/devdesk/internal/scan"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
)

// The Repro line of a finding detail and what Y copies (DEVDESK-752).
//
// SKELETON (DEVDESK-752, red phase): the three functions below exist so the tests
// compile; nothing calls them yet. The coder writes them and wires them in
// details.go (detailsFix), details_actions.go (canCopyFixCommand, copyFixCommand),
// details_fix.go (fixSteps, hasGuidance) and header.go (help).

// reasonToolInContainer is why Y is greyed on a finding the scan reproduced from
// a container: what ran there is not the tool installed on this machine.
const reasonToolInContainer = "The scan ran this tool in a container, not the one on this machine"

// reproCommand is the Repro line of f, trimmed, when it is one line of plain
// words. A Repro read back from a cache is text a scanner build wrote: it is
// checked again here, as runCommand checks a FixCommand.
func reproCommand(f scan.Finding) (string, bool) {
	_ = f
	return "", false
}

// copyCommand is what Y copies and whether it can: the command under Run when
// there is one, else the Repro line, else the reason there is nothing to copy.
func copyCommand(f scan.Finding) (string, shortcut.Availability) {
	if cmd, ok := runCommand(f); ok {
		return cmd, shortcut.Availability{}
	}
	return "", shortcut.Unavailable(reasonNoCommand)
}

// detailsRepro is the Repro line of the Fix block, or nothing.
func detailsRepro(f scan.Finding, t detailsText) []string {
	_, _ = f, t
	return nil
}
