package scan

import (
	"bufio"
	"bytes"
	"context"
	"errors"
	"fmt"
	"io"
	"log"
	"os"
	"path"
	"path/filepath"
	"regexp"
	"strings"

	"gopkg.in/yaml.v3"

	"github.com/anthnel/devdesk/internal/k8s"
)

// A Helm chart or a Kustomize overlay is validated after it is rendered
// (§3.80). Both renderers are optional: without them the directory is
// reported as not rendered, never as clean, and never as a missing tool —
// the schema stage did all it could.
//
// Measured on helm v4.3.0's sources (pkg/cmd/lint.go and
// pkg/chart/v2/lint/support/message.go) and kustomize v5.8.1's Dockerfile:
// alpine/helm's entrypoint is `helm`, the kustomize image's is
// /app/kustomize, so in both the arguments follow the image name.

// Default images for the two renderers.
const (
	DefaultHelmImage      = "alpine/helm"
	DefaultKustomizeImage = "registry.k8s.io/kustomize/kustomize:v5.8.1"
)

// IDs of the findings the renderers themselves produce.
const (
	// HelmLintID is a message helm lint reported, at WARNING or ERROR.
	HelmLintID = "HELM-LINT"
	// K8sRenderID is a chart or an overlay that did not render at all.
	K8sRenderID = "K8S-RENDER"
)

// helmLintLine is one message of helm lint: `[SEVERITY] path: message`, as
// support.Message.Error formats it.
var helmLintLine = regexp.MustCompile(`^\[(ERROR|WARNING|INFO|UNKNOWN)\] ([^:]*): (.*)$`)

// helmSourceLine is the comment helm template writes above each document,
// naming the template it came from: `# Source: <chart name>/templates/x.yaml`.
var helmSourceLine = regexp.MustCompile(`^# Source: (\S+)`)

// renderScope is where a renderer runs. A binary runs in the target and sees
// the whole host. A container sees only mount, read-only at /scan, and works in
// the target inside it: mount is the target itself, or the git repository
// holding it, so an overlay or a chart can reach a sibling of the target as it
// does on the host (DEVDESK-742).
type renderScope struct {
	target string
	mount  string
	// rel is the target relative to mount, with forward slashes; "" when the
	// target is what is mounted.
	rel string
}

// targetOnly mounts the target and nothing else.
func targetOnly(target string) renderScope { return renderScope{target: target, mount: target} }

// workdir is the target inside the container.
func (s renderScope) workdir() string { return path.Join(containerScanPath, s.rel) }

// userHomeDir is the home directory the mount guard keeps out of reach. Tests
// swap it.
var userHomeDir = os.UserHomeDir

// resolveRenderScope asks git, in the target, for the repository holding it.
// Without an answer (no git, not a repository), or when the repository's
// configuration moves its work tree elsewhere (core.worktree, which a cloned
// .git file can bring along), the target alone is mounted.
func resolveRenderScope(ctx context.Context, target string) renderScope {
	git := func(args ...string) ([]byte, error) {
		return runner.Run(ctx, toolCmd{Name: "git", Args: args, Dir: target, Env: gitEnviron(os.Environ())}, nil)
	}
	out, err := git("rev-parse", "--show-toplevel")
	if err != nil {
		log.Printf("[scan/k8s] %s: no git repository to mount, the renderers see the target only: %v", target, err)
		return targetOnly(target)
	}
	worktree, err := git("config", "--get", "core.worktree")
	var exitErr *exitError
	unset := errors.As(err, &exitErr) && exitErr.Code == 1 && len(bytes.TrimSpace(worktree)) == 0
	if !unset {
		log.Printf("[scan/k8s] %s: core.worktree is set or unreadable (%q, %v), the renderers see the target only",
			target, strings.TrimSpace(string(worktree)), err)
		return targetOnly(target)
	}
	scope, ok := widerScope(target, strings.TrimSpace(string(out)))
	if !ok {
		return targetOnly(target)
	}
	log.Printf("[scan/k8s] renderers in a container mount %s, the repository holding %s", scope.mount, target)
	return scope
}

// gitEnviron is env without the variables that point git at another
// repository, work tree or configuration: the mount is decided by the target
// alone. GIT_CEILING_DIRECTORIES stays: it can only stop git's search for the
// repository earlier, and dropping it would widen what the user limited.
func gitEnviron(env []string) []string {
	out := make([]string, 0, len(env))
	for _, kv := range env {
		name, _, _ := strings.Cut(kv, "=")
		switch {
		case name == "GIT_DIR", name == "GIT_WORK_TREE", name == "GIT_COMMON_DIR",
			strings.HasPrefix(name, "GIT_CONFIG"):
			continue
		}
		out = append(out, kv)
	}
	return out
}

// widerScope mounts top, the repository git named, when it is safe to: top is
// a strict ancestor of the target once symlinks are resolved, neither the
// filesystem root nor the home directory nor anything above it, and it holds
// the repository's .git itself (gitDirIsHere). Anything else, an unknown home
// included, keeps the target alone.
func widerScope(target, top string) (renderScope, bool) {
	if top == "" || !filepath.IsAbs(top) {
		return renderScope{}, false
	}
	root, err := filepath.EvalSymlinks(top)
	if err != nil {
		return renderScope{}, false
	}
	real, err := filepath.EvalSymlinks(target)
	if err != nil {
		return renderScope{}, false
	}
	rel, err := filepath.Rel(root, real)
	if err != nil || rel == "." || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return renderScope{}, false
	}
	if filepath.Dir(root) == root {
		return renderScope{}, false
	}
	home, err := userHomeDir()
	if err != nil || home == "" {
		return renderScope{}, false
	}
	if h, err := filepath.EvalSymlinks(home); err == nil {
		home = h
	}
	if r, err := filepath.Rel(root, filepath.Clean(home)); err == nil &&
		(r == "." || (r != ".." && !strings.HasPrefix(r, ".."+string(filepath.Separator)))) {
		return renderScope{}, false
	}
	if !gitDirIsHere(root) {
		return renderScope{}, false
	}
	return renderScope{target: target, mount: root, rel: filepath.ToSlash(rel)}, true
}

// maxGitFile bounds what is read of a .git file or a worktree's gitdir file:
// one line, a path.
const maxGitFile = 4096

// gitDirIsHere reports whether root holds its repository's .git: a directory,
// or the file of a linked worktree ("gitdir: <dir>") whose git directory names
// root's .git back in its own gitdir file. A symlink, a file that says
// anything else, or a git directory that does not point back is refused: git
// was then told where the work tree is, rather than finding it.
func gitDirIsHere(root string) bool {
	dotGit := filepath.Join(root, ".git")
	info, err := os.Lstat(dotGit)
	if err != nil {
		return false
	}
	if info.IsDir() {
		return true
	}
	if !info.Mode().IsRegular() {
		return false
	}
	line, ok := readGitFile(dotGit)
	gitDir, found := strings.CutPrefix(line, "gitdir: ")
	if !ok || !found {
		return false
	}
	if !filepath.IsAbs(gitDir) {
		gitDir = filepath.Join(root, gitDir)
	}
	back, ok := readGitFile(filepath.Join(gitDir, "gitdir"))
	if !ok {
		return false
	}
	if !filepath.IsAbs(back) {
		back = filepath.Join(gitDir, back)
	}
	a, errA := filepath.EvalSymlinks(back)
	b, errB := filepath.EvalSymlinks(dotGit)
	return errA == nil && errB == nil && a == b
}

// readGitFile reads the one line of a small regular file.
func readGitFile(p string) (string, bool) {
	info, err := os.Lstat(p)
	if err != nil || !info.Mode().IsRegular() || info.Size() > maxGitFile {
		return "", false
	}
	data, err := os.ReadFile(p) //nolint:gosec // a .git file of the repository being scanned
	if err != nil {
		return "", false
	}
	return strings.TrimSpace(string(data)), true
}

// renderer runs one tool in the repository, the way every other tool runs:
// in the target for a binary; for an image, with the scope's mount read-only
// at /scan and the target inside it as the working directory.
func renderer(scope renderScope, tool ToolSpec, defaultImage, binary string, args ...string) toolCmd {
	// helm gets them on lint and on template alike: only the flags the two
	// share (--values, --set…) make sense there.
	args = afterSubcommand(args, tool.Args)
	if tool.Source != ToolSourceContainer {
		name := tool.Binary
		if name == "" {
			name = binary
		}
		return toolCmd{Name: name, Args: args, Dir: scope.target}
	}
	return containerRun{
		Flags: []string{"-v", scope.mount + ":" + containerScanPath + ":ro", "-w", scope.workdir()},
		Image: orDefault(tool.Image, defaultImage),
		Argv:  args,
	}.cmd()
}

func orDefault(v, def string) string {
	if v == "" {
		return def
	}
	return v
}

func helmArgs(scope renderScope, chart string, tool ToolSpec, sub string) toolCmd {
	return renderer(scope, tool, DefaultHelmImage, "helm", sub, chart)
}

func kustomizeArgs(scope renderScope, dir string, tool ToolSpec) toolCmd {
	return renderer(scope, tool, DefaultKustomizeImage, "kustomize", "build", dir)
}

// kubeconformStdinArgs validates what arrives on stdin. A container gets -i
// and no repository mount: it reads nothing but its input and its cache.
func kubeconformStdinArgs(rendered []byte, tool ToolSpec, opts KubeconformOptions) toolCmd {
	flags := kubeconformFlags(tool, opts)
	if tool.Source != ToolSourceContainer {
		return toolCmd{Name: kubeconformBinary(tool), Args: append(flags, "-"), Stdin: rendered}
	}
	engineArgs := []string{"-i"}
	if opts.CacheDir != "" {
		engineArgs = append(engineArgs, "-v", opts.CacheDir+":"+kubeconformCacheMount)
	}
	return containerRun{
		Flags: engineArgs, Image: kubeconformImage(tool.Image), Argv: append(flags, "-"), Stdin: rendered,
	}.cmd()
}

// k8sValidation is one schema stage over one repository: the tools it has,
// what it validates against, and the report it fills in.
type k8sValidation struct {
	target string
	// scope is where helm and kustomize run, resolved once per stage.
	scope       renderScope
	kubeconform ToolSpec
	opts        KubeconformOptions
	report      *KubeconformReport
}

// available reports whether an optional renderer was resolved at all.
func available(tool ToolSpec) bool {
	return tool.Source != ToolSourceNone && tool.Source != ""
}

// renderCharts lints, renders and validates each chart. Without helm, every
// chart is reported as not rendered.
func (v *k8sValidation) renderCharts(ctx context.Context, charts []string) error {
	tool := v.opts.Helm
	for _, chart := range charts {
		if !available(tool) {
			v.report.Unrendered = append(v.report.Unrendered, chart)
			continue
		}
		lint := helmLint(ctx, v.scope, chart, tool)
		v.report.Findings = append(v.report.Findings, lint...)

		cmd := helmArgs(v.scope, chart, tool, "template")
		log.Printf("Running: %s", cmd)
		rendered, err := runner.Run(ctx, cmd, nil)
		if err != nil {
			if ctx.Err() != nil {
				return ctx.Err()
			}
			// helm lint renders the chart too, so a chart that does not
			// render has usually been reported by it already, with more to
			// say. The render failure is the fallback, not a second copy.
			if !hasError(lint) {
				v.report.Findings = append(v.report.Findings,
					renderFailure(SourceHelm, "helm", path.Join(chart, "Chart.yaml"), "Chart does not render", tool.Source, nil, "", err))
			}
			continue
		}
		origins := helmOrigins(rendered, chart)
		err = v.validateRendered(ctx, rendered, "helm", func(kind, name string) string {
			if file, ok := origins[kind+"/"+name]; ok {
				return file
			}
			return chart
		})
		if err != nil {
			return fmt.Errorf("chart %s: %w", chart, err)
		}
	}
	return nil
}

// renderKustomizations builds and validates each overlay. Without kustomize,
// every overlay is reported as not rendered.
func (v *k8sValidation) renderKustomizations(ctx context.Context, dirs []string) error {
	tool := v.opts.Kustomize
	for _, dir := range dirs {
		if !available(tool) {
			v.report.Unrendered = append(v.report.Unrendered, dir)
			continue
		}
		file := path.Join(dir, k8s.KustomizationFile(filepath.Join(v.target, filepath.FromSlash(dir))))
		cmd := kustomizeArgs(v.scope, dir, tool)
		log.Printf("Running: %s", cmd)
		rendered, err := runner.Run(ctx, cmd, nil)
		if err != nil {
			if ctx.Err() != nil {
				return ctx.Err()
			}
			v.report.Findings = append(v.report.Findings,
				renderFailure(SourceKustomize, "kustomize", file, "Overlay does not build", tool.Source, nil, "", err))
			continue
		}
		// kustomize adds no origin to what it emits unless the kustomization
		// asks for it, and DevDesk does not write into the file to ask. The
		// overlay is what was built, so it is what a finding points at.
		err = v.validateRendered(ctx, rendered, "kustomize", func(string, string) string { return file })
		if err != nil {
			return fmt.Errorf("overlay %s: %w", dir, err)
		}
	}
	return nil
}

// validateRendered runs kubeconform over rendered YAML and points each
// finding back at the file it came from. A rendered line is not a line of
// any file in the repository, so these findings carry none.
func (v *k8sValidation) validateRendered(ctx context.Context, rendered []byte, dialect string, origin func(kind, name string) string) error {
	if len(bytes.TrimSpace(rendered)) == 0 {
		return nil
	}
	cmd := kubeconformStdinArgs(rendered, v.kubeconform, v.opts)
	log.Printf("Running: %s", cmd)
	out, err := runner.Run(ctx, cmd, nil)
	if err := kubeconformFailure(out, err); err != nil {
		return err
	}
	noFile := func(string) ([]byte, error) { return nil, errors.New("rendered, not a file") }
	findings, skipped, err := parseKubeconformOutput(out, v.opts.KubernetesVersion, noFile, origin)
	if err != nil {
		return err
	}
	v.report.SkippedCustom += skipped
	for i := range findings {
		findings[i].IaCType = dialect
	}
	v.report.Findings = append(v.report.Findings, findings...)
	return nil
}

// helmLint runs helm lint and returns its warnings and errors. helm exits 1
// when a chart fails; its messages are still the answer. A run that printed
// nothing parseable is logged and yields nothing — the render that follows
// will say whether the chart is usable.
func helmLint(ctx context.Context, scope renderScope, chart string, tool ToolSpec) []Finding {
	cmd := helmArgs(scope, chart, tool, "lint")
	log.Printf("Running: %s", cmd)
	out, err := runner.Run(ctx, cmd, nil)
	findings, recognised := parseHelmLint(out, chart, scope)
	if err != nil && !recognised {
		log.Printf("ERROR [scan/helm] lint %s: %v", chart, err)
	}
	return findings
}

// parseHelmLint turns helm lint's text into findings. The second result says
// the output was helm lint's at all.
//
// A message's path is usually relative to the chart ("templates/cm.yaml"),
// but not always: the missing-dependency warning names the chart directory
// absolutely — "/scan/charts/broken" in a container, measured on helm 4.3.0.
// Both are brought back to a path relative to the target.
func parseHelmLint(out []byte, chart string, scope renderScope) ([]Finding, bool) {
	file := func(p string) string { return helmLintPath(p, chart, scope) }
	var findings []Finding
	recognised := false
	sc := bufio.NewScanner(bytes.NewReader(out))
	for sc.Scan() {
		line := strings.TrimSpace(sc.Text())
		switch {
		case strings.HasPrefix(line, "==> Linting"):
			recognised = true
		case strings.HasPrefix(line, "Error "):
			// Printed instead of the messages when the chart could not be
			// loaded at all.
			recognised = true
			findings = append(findings, helmLintFinding(chart, SeverityHigh, strings.TrimPrefix(line, "Error ")))
		default:
			m := helmLintLine.FindStringSubmatch(line)
			if m == nil {
				continue
			}
			recognised = true
			switch m[1] {
			case "ERROR":
				findings = append(findings, helmLintFinding(file(m[2]), SeverityHigh, m[3]))
			case "WARNING":
				findings = append(findings, helmLintFinding(file(m[2]), SeverityLow, m[3]))
			}
		}
	}
	return findings, recognised
}

// helmLintPath resolves a path helm lint printed to one relative to the
// target. In a container the target is the scope's working directory, which is
// /scan itself unless the git repository around the target is mounted.
func helmLintPath(p, chart string, scope renderScope) string {
	p = strings.TrimSuffix(p, "/")
	switch {
	case p == containerScanPath || strings.HasPrefix(p, containerScanPath+"/"):
		if rel, err := filepath.Rel(filepath.FromSlash(scope.workdir()), filepath.FromSlash(p)); err == nil {
			return filepath.ToSlash(rel)
		}
		return p
	case filepath.IsAbs(p):
		if rel, err := filepath.Rel(scope.target, p); err == nil && !strings.HasPrefix(rel, "..") {
			return filepath.ToSlash(rel)
		}
		return filepath.ToSlash(p)
	default:
		return path.Join(chart, p)
	}
}

func helmLintFinding(file string, severity SeverityLevel, msg string) Finding {
	return Finding{
		ID:          HelmLintID,
		Title:       msg,
		Description: "helm lint reported this about the chart.",
		Message:     msg,
		Severity:    severity,
		Source:      SourceHelm,
		File:        file,
		IaCType:     "helm",
	}
}

func hasError(findings []Finding) bool {
	for _, f := range findings {
		if f.Severity == SeverityHigh {
			return true
		}
	}
	return false
}

// renderFailure is a chart or an overlay that could not be rendered: nothing
// in it was validated, and `helm install` or `kubectl apply -k` would fail the
// same way.
//
// steps and repro are what the caller wrote for it (renderSteps, localRepro);
// from is where the renderer ran.
//
// SKELETON (DEVDESK-752, red phase): steps, repro and from are not recorded yet.
func renderFailure(source, dialect, file, title string, from ToolSource, steps []string, repro string, err error) Finding {
	_, _ = steps, repro
	detail := err.Error()
	var exitErr *exitError
	if errors.As(err, &exitErr) && exitErr.Stderr != "" {
		detail = strings.TrimSpace(exitErr.Stderr)
	}
	first, _, _ := strings.Cut(detail, "\n")
	return Finding{
		ID:          K8sRenderID,
		Title:       title + ": " + first,
		Description: "The directory could not be rendered, so none of its resources were validated.",
		Message:     detail,
		Resolution:  renderResolution(source, from, detail),
		Severity:    SeverityHigh,
		Source:      source,
		File:        file,
		IaCType:     dialect,
	}
}

// How to fix a chart or an overlay that does not render, in the renderer's own
// terms.
const (
	helmRenderResolution = "Render it locally with helm template and fix what it reports; " +
		"a chart's dependencies must be vendored in charts/ or fetched with helm dependency build."
	kustomizeRenderResolution = "Build it locally with kustomize build (or kubectl kustomize) and fix what it reports."
	// kustomize's load restrictor (LoadRestrictionsRootOnly, its default)
	// refuses a file outside the kustomization's directory, with this message.
	// The flag is not reserved (ToolKustomize.ReservedArgs) and lands after
	// `build` (afterSubcommand), where kustomize accepts it.
	loadRestrictorResolution = "kustomize refuses by default a file outside the overlay directory " +
		"(same as kubectl apply -k). Reference a directory with its own kustomization instead, " +
		"or, if your deployment tool allows it, set " +
		"scan.tools.kustomize.args: [--load-restrictor=LoadRestrictionsNone]."
)

// mountResolution is added for a kustomize image that could not find a path:
// the container sees only what DevDesk mounts (renderScope), and DevDesk does
// not walk the repository to tell a hidden reference from a broken one.
// ToolConfig's `source` key takes auto, binary or image.
const mountResolution = "If this reference points outside the directory DevDesk mounts into the container " +
	"(the scanned directory, or its git repository when it has one), scan the enclosing directory, " +
	"or set scan.tools.kustomize.source: binary (the binary sees the whole file system)."

// renderResolution picks the advice for a render failure from the renderer,
// where it ran and what it printed.
func renderResolution(source string, from ToolSource, detail string) string {
	if source != SourceKustomize {
		return helmRenderResolution
	}
	advice := kustomizeRenderResolution
	if strings.Contains(detail, "security; file") && strings.Contains(detail, "is not in or below") {
		advice = loadRestrictorResolution
	}
	if from == ToolSourceContainer &&
		(strings.Contains(detail, "evalsymlink failure") || strings.Contains(detail, "no such file or directory")) {
		advice += " " + mountResolution
	}
	return advice
}

// helmOrigins maps each rendered resource, by kind and name, to the template
// it came from, relative to the repository. helm names the template under the
// chart's own name, which need not be its directory's.
func helmOrigins(rendered []byte, chart string) map[string]string {
	origins := map[string]string{}
	for _, doc := range splitYAMLDocuments(rendered) {
		var source string
		for _, line := range strings.Split(doc, "\n") {
			if m := helmSourceLine.FindStringSubmatch(line); m != nil {
				source = m[1]
				break
			}
		}
		if source == "" {
			continue
		}
		var meta struct {
			Kind     string `yaml:"kind"`
			Metadata struct {
				Name string `yaml:"name"`
			} `yaml:"metadata"`
		}
		if yaml.Unmarshal([]byte(doc), &meta) != nil || meta.Kind == "" {
			continue
		}
		key := meta.Kind + "/" + meta.Metadata.Name
		if _, seen := origins[key]; seen {
			continue
		}
		_, rest, _ := strings.Cut(source, "/")
		origins[key] = path.Join(chart, rest)
	}
	return origins
}

// splitYAMLDocuments splits a multi-document stream on its `---` separators.
func splitYAMLDocuments(stream []byte) []string {
	var docs []string
	var cur strings.Builder
	r := bufio.NewReader(bytes.NewReader(stream))
	for {
		line, err := r.ReadString('\n')
		if strings.TrimRight(line, "\r\n") == "---" {
			docs = append(docs, cur.String())
			cur.Reset()
		} else {
			cur.WriteString(line)
		}
		if errors.Is(err, io.EOF) || err != nil {
			break
		}
	}
	return append(docs, cur.String())
}

package scan

import (
	"context"
	"errors"
	"fmt"
	"log"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"sync"

	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/k8s"
)

// kubeconform validates Kubernetes manifests against the API's JSON schemas
// (§3.80): a wrong type, a missing required field, an unknown field under
// -strict, an apiVersion the target release no longer serves. Trivy's
// misconfiguration scan already lints the same files for security; this is
// the other question — whether the API server would accept them at all.
//
// Measured against kubeconform v0.8.0's sources, not its README: the JSON
// output, the status strings and the "could not find schema" wording below are
// what pkg/output/json.go and pkg/validator/validator.go write.

// DefaultKubeconformImage is the image kubeconform runs from in a container.
// Its entrypoint is the binary itself, so the arguments follow the image name.
const DefaultKubeconformImage = "ghcr.io/yannh/kubeconform"

// kubeconformCacheMount is where the schema cache is mounted in a container.
const kubeconformCacheMount = "/cache"

// KubeconformOptions is what one validation run needs beyond the tool itself.
type KubeconformOptions struct {
	// KubernetesVersion is the release to validate against, x.y.z or master.
	KubernetesVersion string
	// CacheDir is where downloaded schemas are kept between runs. Empty means
	// every run downloads them again — slower, not wrong.
	CacheDir string
	// Helm and Kustomize render charts and overlays before validation. Either
	// may be unresolved (Source none), which leaves what it would have
	// rendered unvalidated and says so in the report.
	Helm      ToolSpec
	Kustomize ToolSpec
}

// KubeconformReport is what one run found, beyond its findings.
type KubeconformReport struct {
	Findings []Finding
	// Validated is how many files were handed to kubeconform.
	Validated int
	// Unrendered are the charts and Kustomize overlays nobody validated,
	// because the tool that renders them was not available. They are not
	// errors — the scan did everything it could — but they are not "clean"
	// either, and saying nothing would read as though they were.
	Unrendered []string
	// SkippedCustom counts resources whose kind no schema describes because it
	// is a custom resource. Their schema lives in the CRD, which kubeconform
	// does not read.
	SkippedCustom int
}

// kubeconformArgs builds the invocation over files relative to target.
//
// The files are passed explicitly rather than the directory: kubeconform
// reports "missing 'kind' key" on every YAML file that is not a manifest —
// a CI configuration, a Helm values file — and k8s.Discover has already told
// the two apart. The tool runs in target so the file names it reports are the
// relative ones the findings carry.
func kubeconformArgs(target string, files []string, tool ToolSpec, opts KubeconformOptions) toolCmd {
	docker := tool.Source == ToolSourceContainer
	flags := kubeconformFlags(tool, opts)

	if !docker {
		args := append(flags, nativePaths(files)...)
		return toolCmd{Name: kubeconformBinary(tool), Args: args, Dir: target}
	}

	engineArgs := []string{"-v", target + ":" + containerScanPath + ":ro"}
	if opts.CacheDir != "" {
		engineArgs = append(engineArgs, "-v", opts.CacheDir+":"+kubeconformCacheMount)
	}
	engineArgs = append(engineArgs, "-w", containerScanPath)
	// Inside the container the paths are Linux ones, whatever the host is.
	return containerRun{Flags: engineArgs, Image: kubeconformImage(tool.Image), Argv: append(flags, files...)}.cmd()
}

// kubeconformFlags are the options every validation run shares, raw files or
// rendered input.
func kubeconformFlags(tool ToolSpec, opts KubeconformOptions) []string {
	// The user's flags first: there is no subcommand, and Go's flag package
	// stops at the first positional argument.
	flags := append(append([]string{}, tool.Args...), "-output", "json", "-strict")
	if opts.KubernetesVersion != "" {
		flags = append(flags, "-kubernetes-version", opts.KubernetesVersion)
	}
	if opts.CacheDir != "" {
		cache := opts.CacheDir
		if tool.Source == ToolSourceContainer {
			cache = kubeconformCacheMount
		}
		flags = append(flags, "-cache", cache)
	}
	return flags
}

// RunKubeconform finds the repository's manifests and validates them: the
// plain ones as files, the charts and overlays once rendered.
//
// The plain manifests are skipped when there are none rather than handed over
// as an empty list: kubeconform with no file argument reads stdin, and would
// wait there.
func RunKubeconform(ctx context.Context, target string, tool ToolSpec, opts KubeconformOptions, progressFn func(string)) (*KubeconformReport, error) {
	layout, err := k8s.Discover(target)
	if err != nil {
		return nil, fmt.Errorf("listing manifests: %w", err)
	}
	if opts.CacheDir != "" {
		if err := os.MkdirAll(opts.CacheDir, 0o755); err != nil {
			// Validation still works without a cache; it downloads each time.
			opts.CacheDir = ""
		}
	}
	v := &k8sValidation{target: target, scope: targetOnly(target), kubeconform: tool, opts: opts,
		report: &KubeconformReport{Validated: len(layout.Manifests)}}
	// Only a renderer in a container needs more than the target mounted, and
	// git is asked only when one is about to run.
	if (len(layout.Charts) > 0 && opts.Helm.Source == ToolSourceContainer) ||
		(len(layout.Kustomizations) > 0 && opts.Kustomize.Source == ToolSourceContainer) {
		v.scope = resolveRenderScope(ctx, target)
	}

	if len(layout.Manifests) > 0 {
		if err := v.validateFiles(ctx, layout.Manifests, progressFn); err != nil {
			return nil, err
		}
	}
	if err := v.renderCharts(ctx, layout.Charts); err != nil {
		return nil, err
	}
	if err := v.renderKustomizations(ctx, layout.Kustomizations); err != nil {
		return nil, err
	}
	return v.report, nil
}

// validateFiles validates plain manifests, where each finding can be given the
// line its pointer designates.
func (v *k8sValidation) validateFiles(ctx context.Context, files []string, progressFn func(string)) error {
	cmd := kubeconformArgs(v.target, files, v.kubeconform, v.opts)
	log.Printf("Running: %s", cmd)
	out, err := runner.Run(ctx, cmd, progressFn)
	if err := kubeconformFailure(out, err); err != nil {
		return err
	}
	findings, skipped, err := parseKubeconformOutput(out, v.opts.KubernetesVersion, fileReader(v.target), nil)
	if err != nil {
		return err
	}
	v.report.Findings = append(v.report.Findings, findings...)
	v.report.SkippedCustom += skipped
	return nil
}

// kubeconformFailure tells a run that found problems from one that failed.
// kubeconform exits 1 for both; what separates them is whether it wrote its
// JSON report.
func kubeconformFailure(out []byte, err error) error {
	if err == nil {
		return nil
	}
	var exitErr *exitError
	if errors.As(err, &exitErr) && exitErr.Code == 1 && looksLikeJSON(out) {
		return nil
	}
	return err
}

func looksLikeJSON(out []byte) bool {
	for _, b := range out {
		switch b {
		case ' ', '\n', '\r', '\t':
			continue
		case '{':
			return true
		default:
			return false
		}
	}
	return false
}

// fileReader reads a file relative to root, for locating a finding's line.
func fileReader(root string) func(string) ([]byte, error) {
	return func(name string) ([]byte, error) {
		return os.ReadFile(filepath.Join(root, filepath.FromSlash(name))) //nolint:gosec // a manifest of the repository being scanned
	}
}

// nativePaths turns the discovered, slash-separated names into the host's.
func nativePaths(files []string) []string {
	out := make([]string, len(files))
	for i, f := range files {
		out[i] = filepath.FromSlash(f)
	}
	return out
}

func kubeconformImage(image string) string {
	if image == "" {
		return DefaultKubeconformImage
	}
	return image
}

func kubeconformBinary(tool ToolSpec) string {
	if tool.Binary != "" {
		return tool.Binary
	}
	return "kubeconform"
}

// KubeconformCacheDir is where schemas are cached: beside the scan caches,
// under ~/.devdesk/cache. Empty when there is no home directory, which only
// costs the cache.
func KubeconformCacheDir() string {
	home, err := os.UserHomeDir()
	if err != nil {
		return ""
	}
	return filepath.Join(home, ".devdesk", "cache", "kubeconform")
}

// kubernetesVersionPattern is what kubeconform accepts for -kubernetes-version:
// its own regexp, from pkg/config/config.go.
var kubernetesVersionPattern = regexp.MustCompile(`^(master|\d+\.\d+\.\d+)$`)

// ValidateKubernetesVersion refuses what kubeconform would refuse, so the
// configuration view says it at the field rather than every scan failing on
// it. Empty is accepted: it means the default release.
func ValidateKubernetesVersion(v string) error {
	if v == "" || kubernetesVersionPattern.MatchString(v) {
		return nil
	}
	return fmt.Errorf("%q is not a version: use a full x.y.z such as %s, or master", v, config.DefaultKubernetesVersion)
}

// kubeconformOptions is what this scanner validates against, and the
// renderers it has — an unavailable one is handed over unresolved.
func (s *Scanner) kubeconformOptions() KubeconformOptions {
	opts := KubeconformOptions{KubernetesVersion: s.options.Tools.Kubeconform.KubernetesVersion, CacheDir: KubeconformCacheDir()}
	// A renderer serves only when it is ticked: installed and unticked, it is
	// not used (§3.86), and its charts or overlays are reported as not rendered.
	if s.runs(CategoryIDMisconfig, ToolHelm, TargetDirectory) {
		opts.Helm = s.spec(ToolHelm)
	}
	if s.runs(CategoryIDMisconfig, ToolKustomize, TargetDirectory) {
		opts.Kustomize = s.spec(ToolKustomize)
	}
	return opts
}

// runKubeconformStage is the schema stage of Scan, shaped like the others:
// progress, then findings or a stage error under the result's lock.
func (s *Scanner) runKubeconformStage(ctx context.Context, target string, result *Result, mu *sync.Mutex, notify func(ProgressUpdate)) {
	const stage, label = "k8s-schema", "Kubernetes schema"
	notify(ProgressUpdate{Stage: stage, Label: label, Status: StageRunning})
	progressFn := func(detail string) {
		notify(ProgressUpdate{Stage: stage, Label: label, Status: StageRunning, Detail: detail})
	}
	report, err := RunKubeconform(ctx, target, s.spec(ToolKubeconform), s.kubeconformOptions(), progressFn)

	mu.Lock()
	defer mu.Unlock()
	if err != nil {
		recordStageError(result, "kubeconform", err)
		notify(ProgressUpdate{Stage: stage, Label: label, Status: StageError, Detail: err.Error()})
		return
	}
	if report.SkippedCustom > 0 {
		log.Printf("[scan/kubeconform] %s: %d custom resources not validated (their schema is in a CRD)", target, report.SkippedCustom)
	}
	if len(report.Unrendered) > 0 {
		log.Printf("[scan/kubeconform] %s: not rendered, so not validated: %s", target, strings.Join(report.Unrendered, ", "))
	}
	result.K8sUnrendered = report.Unrendered
	result.Findings = append(result.Findings, report.Findings...)
	// Schema validation is the second half of the Misconfiguration category, so
	// a run of it makes the verdict known on its own: a repository scanned with
	// Trivy's rules switched off but kubeconform on has been looked at, and a
	// "-" there would say otherwise. What the stage could not render is carried
	// in K8sUnrendered and comes back out as the column's "?".
	result.MisconfigScanned = true
	notify(ProgressUpdate{Stage: stage, Label: label, Status: StageDone})
}
package scan

import (
	"encoding/json"
	"fmt"
	"regexp"
	"strings"

	"github.com/anthnel/devdesk/internal/k8s"
)

// The identities a kubeconform finding carries. They are DevDesk's, not the
// tool's — kubeconform has no rule ids — and they are stable so that a
// re-scan can say whether a finding went away.
const (
	// K8sSchemaID is a resource that does not match its kind's schema.
	K8sSchemaID = "K8S-SCHEMA"
	// K8sAPIRemovedID is a built-in kind asked for under an apiVersion the
	// target release does not serve.
	K8sAPIRemovedID = "K8S-API-REMOVED"
	// K8sParseID is a document kubeconform could not read as a resource.
	K8sParseID = "K8S-PARSE"
)

// K8sDeprecationGuide is where a removed apiVersion is explained, per kind.
const K8sDeprecationGuide = "https://kubernetes.io/docs/reference/using-api/deprecation-guide/"

// kubeconform's status strings, as pkg/output/json.go writes them.
const (
	kubeconformInvalid = "statusInvalid"
	kubeconformError   = "statusError"
)

const kubeconformMissingSchema = "could not find schema for "

// builtinGroups are the API groups Kubernetes itself serves. A resource of one
// of them with no schema was asked for under a version the release no longer
// has; a resource of any other group is a custom one, whose schema is in a CRD
// kubeconform does not read.
//
// A closed list, not a suffix rule: several CRD groups end in ".k8s.io" too —
// the Gateway API's gateway.networking.k8s.io, the snapshot controller's
// snapshot.storage.k8s.io — and a suffix rule would report every Gateway as a
// removed API.
var builtinGroups = map[string]bool{
	"":                             true, // core, "v1"
	"admissionregistration.k8s.io": true,
	"apiextensions.k8s.io":         true,
	"apiregistration.k8s.io":       true,
	"apps":                         true,
	"authentication.k8s.io":        true,
	"authorization.k8s.io":         true,
	"autoscaling":                  true,
	"batch":                        true,
	"certificates.k8s.io":          true,
	"coordination.k8s.io":          true,
	"discovery.k8s.io":             true,
	"events.k8s.io":                true,
	"extensions":                   true,
	"flowcontrol.apiserver.k8s.io": true,
	"internal.apiserver.k8s.io":    true,
	"networking.k8s.io":            true,
	"node.k8s.io":                  true,
	"policy":                       true,
	"rbac.authorization.k8s.io":    true,
	"resource.k8s.io":              true,
	"scheduling.k8s.io":            true,
	"storage.k8s.io":               true,
	"storagemigration.k8s.io":      true,
}

// additionalProperty is how the schema library words an unknown field under
// -strict. The path it comes with is the parent's, so the key named here is
// what locates the line.
var additionalProperty = regexp.MustCompile(`additional properties? '([^']+)'`)

type kubeconformOutput struct {
	Resources []kubeconformResource `json:"resources"`
}

type kubeconformResource struct {
	Filename         string                    `json:"filename"`
	Kind             string                    `json:"kind"`
	Name             string                    `json:"name"`
	Version          string                    `json:"version"`
	Status           string                    `json:"status"`
	Msg              string                    `json:"msg"`
	ValidationErrors []kubeconformFieldProblem `json:"validationErrors"`
}

type kubeconformFieldProblem struct {
	Path string `json:"path"`
	Msg  string `json:"msg"`
}

// parseKubeconformOutput turns the report into findings, and counts the custom
// resources nobody could validate. read returns a manifest's content by the
// name kubeconform reported, to find the line a pointer designates; a file it
// cannot read keeps its findings, at line 0.
//
// origin, when not nil, names the file a resource came from — for rendered
// input, where kubeconform can only say "stdin".
func parseKubeconformOutput(out []byte, version string, read func(string) ([]byte, error), origin func(kind, name string) string) ([]Finding, int, error) {
	var report kubeconformOutput
	if err := json.Unmarshal(out, &report); err != nil {
		return nil, 0, fmt.Errorf("parsing kubeconform output: %w", err)
	}

	contents := map[string][]byte{}
	content := func(name string) []byte {
		if c, ok := contents[name]; ok {
			return c
		}
		c, err := read(name)
		if err != nil {
			c = nil
		}
		contents[name] = c
		return c
	}

	var findings []Finding
	skipped := 0
	for _, r := range report.Resources {
		if origin != nil {
			r.Filename = origin(r.Kind, r.Name)
		}
		switch r.Status {
		case kubeconformInvalid:
			findings = append(findings, schemaFindings(r, content(r.Filename))...)
		case kubeconformError:
			f, custom := errorFinding(r, version, content(r.Filename))
			if custom {
				skipped++
				continue
			}
			findings = append(findings, f)
		}
	}
	return findings, skipped, nil
}

// schemaFindings is one finding per field the schema rejected, so each one has
// its own line and can be fixed on its own.
func schemaFindings(r kubeconformResource, content []byte) []Finding {
	problems := r.ValidationErrors
	if len(problems) == 0 {
		// An invalid resource with no field detail still gets reported, on the
		// resource as a whole.
		problems = []kubeconformFieldProblem{{Msg: r.Msg}}
	}
	out := make([]Finding, 0, len(problems))
	for _, p := range problems {
		f := k8sFinding(r, K8sSchemaID)
		f.Title = fmt.Sprintf("%s: %s", resourceLabel(r), p.Msg)
		f.Description = fmt.Sprintf("The resource does not match the schema of %s %s: the API server would reject it.", r.Version, r.Kind)
		f.Message = strings.TrimSpace(pointerLabel(p.Path) + " " + p.Msg)
		f.Resolution = "Correct the field so it matches the API's schema for this kind and apiVersion."
		f.Line, f.EndLine = locateProblem(content, r, p)
		out = append(out, f)
	}
	return out
}

// errorFinding classifies a resource kubeconform could not validate. The
// second result says it is a custom resource, which is skipped rather than
// reported: its schema is not missing, it lives somewhere kubeconform does not
// look.
func errorFinding(r kubeconformResource, version string, content []byte) (Finding, bool) {
	if strings.HasPrefix(r.Msg, kubeconformMissingSchema) {
		if !builtinGroups[apiGroup(r.Version)] {
			return Finding{}, true
		}
		f := k8sFinding(r, K8sAPIRemovedID)
		f.Title = fmt.Sprintf("%s: %s %s is not served by Kubernetes %s", resourceLabel(r), r.Version, r.Kind, version)
		f.Description = "This apiVersion has been removed from the Kubernetes release the manifests are validated against: the API server would refuse the resource."
		f.Message = r.Msg
		f.Resolution = fmt.Sprintf("Migrate %s to an apiVersion Kubernetes %s serves; some migrations also change fields.", r.Kind, version)
		f.References = []string{K8sDeprecationGuide}
		if span, ok := k8s.DocumentField(content, r.Kind, r.Name, "apiVersion"); ok {
			f.Line, f.EndLine = span.Line, span.EndLine
		}
		return f, false
	}
	f := k8sFinding(r, K8sParseID)
	f.Title = "Cannot be read as a Kubernetes resource"
	if r.Kind != "" {
		f.Title = resourceLabel(r) + ": cannot be read as a Kubernetes resource"
	}
	f.Description = "kubeconform could not parse this document as a resource."
	f.Message = r.Msg
	f.Resolution = "Check the document's YAML syntax and that it carries apiVersion, kind and metadata."
	return f, false
}

// k8sFinding is what every kubeconform finding shares.
func k8sFinding(r kubeconformResource, id string) Finding {
	return Finding{
		ID:       id,
		Severity: SeverityHigh,
		Source:   SourceKubeconform,
		File:     r.Filename,
		IaCType:  "kubernetes",
	}
}

// locateProblem finds the line of one rejected field. An unknown field is
// reported at its parent, with the key in the message; the key's own line is
// the one to show, and the parent's is the fallback.
func locateProblem(content []byte, r kubeconformResource, p kubeconformFieldProblem) (int, int) {
	if content == nil {
		return 0, 0
	}
	if m := additionalProperty.FindStringSubmatch(p.Msg); m != nil {
		if span, ok := k8s.Locate(content, r.Kind, r.Name, strings.TrimSuffix(p.Path, "/")+"/"+escapePointer(m[1])); ok {
			return span.Line, span.EndLine
		}
	}
	if span, ok := k8s.Locate(content, r.Kind, r.Name, p.Path); ok {
		return span.Line, span.EndLine
	}
	return 0, 0
}

// apiGroup is the group of an apiVersion: "apps" for apps/v1, "" for v1.
func apiGroup(apiVersion string) string {
	if i := strings.LastIndex(apiVersion, "/"); i >= 0 {
		return apiVersion[:i]
	}
	return ""
}

func resourceLabel(r kubeconformResource) string {
	if r.Name == "" {
		return r.Kind
	}
	return r.Kind + "/" + r.Name
}

func pointerLabel(path string) string {
	if path == "" {
		return ""
	}
	return path + ":"
}

func escapePointer(key string) string {
	return strings.ReplaceAll(strings.ReplaceAll(key, "~", "~0"), "/", "~1")
}

