package security

import (
	"path/filepath"
	"strconv"
	"strings"

	"github.com/anthnel/devdesk/internal/remediation"
	"github.com/anthnel/devdesk/internal/scan"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
)

// fixState is the state behind the Fix line of a finding detail (DEVDESK-751).
type fixState int

const (
	fixManual fixState = iota
	fixBuiltIn
	fixBuiltInDeclined
	fixNoFixPublished
	fixCannotFixHere
	fixNoGuidance
)

// The closed vocabulary of the Fix line (AC1). Only labelBuiltInUnavailable
// carries a reason, which Label appends after a colon.
const (
	labelBuiltInAvailable   = "Built-in fix available"
	labelBuiltInUnavailable = "Built-in fix unavailable"
	labelManual             = "Manual"
	labelNoFixPublished     = "No fix published"
	labelCannotFixHere      = "Cannot fix here"
	labelNoGuidance         = "No guidance available"
)

// Reasons a finding's file cannot be opened from the detail (Rule 130).
const (
	reasonFileOutsideTarget = "This file is outside the scanned directory"
	reasonNoFile            = "This finding names no file"
	// reasonFileLinkOutsideTarget is the answer of enter, which follows links:
	// the header cannot know it (it reads no disk).
	reasonFileLinkOutsideTarget = "This file is reached through a link that leaves the scanned directory"
)

// fixStatus is the Fix line of a finding detail, in words: a colour or a key
// name alone would not say it (Rule 134), so the status never names a key.
type fixStatus struct {
	State   fixState
	Reason  string // why the built-in fix is unavailable or cannot run here
	Effect  string // what the fix does: the catalog rule's title, or "Fixed in <v>"
	Warning string // remediation.Rule.Warning, or ""
}

// Label is the closed-vocabulary text of the status.
func (s fixStatus) Label() string {
	switch s.State {
	case fixBuiltIn:
		return labelBuiltInAvailable
	case fixBuiltInDeclined:
		return labelBuiltInUnavailable + ": " + s.Reason
	case fixManual:
		return labelManual
	case fixNoFixPublished:
		return labelNoFixPublished
	case fixCannotFixHere:
		return labelCannotFixHere
	}
	return labelNoGuidance
}

// fixStatusOf says whether f can be fixed and why not. For a misconfiguration
// it reads misconfigFixAvailability, the computation behind the shortcut column,
// so the detail and the header agree (Rule 130).
func fixStatusOf(f scan.Finding, onDisk bool) fixStatus {
	switch scan.Categorize(f) {
	case scan.CategoryMisconfiguration:
		return misconfigFixStatus(f, onDisk)
	case scan.CategoryVulnerability:
		if f.FixedIn != "" {
			return fixStatus{State: fixManual, Effect: "Fixed in " + f.FixedIn}
		}
		return fixStatus{State: fixNoFixPublished}
	}
	return guidanceStatus(f)
}

// misconfigFixStatus is the status of a misconfiguration, in the order of
// misconfigFixAvailability: an image first, then the catalog, then the guidance
// a finding the catalog does not know can still carry.
func misconfigFixStatus(f scan.Finding, onDisk bool) fixStatus {
	rule, a := misconfigFixAvailability(f, onDisk)
	switch {
	case !onDisk:
		return fixStatus{State: fixCannotFixHere, Reason: a.Reason}
	case a.Enabled():
		return fixStatus{State: fixBuiltIn, Effect: rule.Title, Warning: rule.Warning}
	case rule.AVDID != "":
		return fixStatus{State: fixBuiltInDeclined, Reason: a.Reason}
	}
	return guidanceStatus(f)
}

// guidanceStatus is Manual when the finding tells how to fix it by hand, and
// No guidance available when it does not.
func guidanceStatus(f scan.Finding) fixStatus {
	if hasGuidance(f) {
		return fixStatus{State: fixManual}
	}
	return fixStatus{State: fixNoGuidance}
}

// hasGuidance says whether f carries any instruction: a Resolution, a
// FixCommand or a remediation.MissingFor text.
func hasGuidance(f scan.Finding) bool {
	if f.Resolution != "" || f.FixCommand != "" {
		return true
	}
	_, ok := remediation.MissingFor(f)
	return ok
}

// runCommand is the text under Run and the text Y copies: the FixCommand trimmed,
// when fixAction calls it a command and it is plain words. One computation, two
// readers.
//
// The command is pasted into a shell, and its names and versions come from a
// scan, so anything but words is refused (DEVDESK-751): a line break, a control
// character (an escape sequence, a tab, a carriage return), a blank other than a
// single space, a character that has no visible form (a zero-width or
// right-to-left mark) or a shell metacharacter. A refused command is not lost:
// fixSteps shows its text under Do.
func runCommand(f scan.Finding) (string, bool) {
	label, text := fixAction(f)
	cmd := strings.TrimSpace(text)
	if label != "Run" || cmd == "" || !scan.PlainWords(cmd) {
		return "", false
	}
	return cmd, true
}

// fixSteps are the numbered steps under Do: what a rule the catalog cannot fix
// is missing, and a FixCommand that is not offered under Run: a sentence rather
// than a command, or a command runCommand refuses.
func fixSteps(f scan.Finding) []string {
	var steps []string
	if _, inCatalog := remediation.FixFor(f); !inCatalog {
		if text, ok := remediation.MissingFor(f); ok {
			steps = append(steps, text)
		}
	}
	if _, offered := runCommand(f); !offered {
		if _, text := fixAction(f); strings.TrimSpace(text) != "" {
			steps = append(steps, text)
		}
	}
	return steps
}

// fact is one labelled value of the Where section.
type fact struct{ Label, Value string }

// whereFacts are the facts under Where, in order: File, Package, Job, Script,
// Match. A path is shown the way shortPaths shows it, with its line.
func whereFacts(f scan.Finding, target string) []fact {
	var facts []fact
	add := func(label, value string) {
		if value != "" {
			facts = append(facts, fact{label, value})
		}
	}
	file := shortPaths(f.File, target)
	if file != "" && f.Line > 0 {
		file += ":" + strconv.Itoa(f.Line)
	}
	add("File", file)
	add("Package", packageFact(f))
	add("Job", f.Job)
	add("Script", f.ScriptLine)
	add("Match", f.Match)
	return facts
}

// packageFact is "name version (kind)", leaving out what is unknown.
func packageFact(f scan.Finding) string {
	if f.PkgName == "" {
		return ""
	}
	out := f.PkgName
	if f.Version != "" {
		out += " " + f.Version
	}
	if kind := packageKind(f.Class); kind != "" {
		out += " (" + kind + ")"
	}
	return out
}

// findingFilePath is the absolute path of the finding's file under the scanned
// directory, or the reason it cannot be opened. It does no I/O: whether the file
// exists is for the viewer to say (Rule 130, "Not knowing"). A path that leaves
// the target, by a parent segment or an absolute path elsewhere, is refused.
func findingFilePath(f scan.Finding, target string, onDisk bool) (string, shortcut.Availability) {
	if !onDisk {
		return "", shortcut.Unavailable(reasonFileNotOnDisk)
	}
	if f.File == "" {
		return "", shortcut.Unavailable(reasonNoFile)
	}
	root := filepath.Clean(target)
	file := filepath.ToSlash(f.File)
	var path string
	switch {
	case file == scanMount || strings.HasPrefix(file, scanMount+"/"):
		path = filepath.Join(root, filepath.FromSlash(strings.TrimPrefix(file, scanMount)))
	case filepath.IsAbs(f.File):
		path = filepath.Clean(f.File)
	default:
		path = filepath.Join(root, filepath.FromSlash(file))
	}
	rel, err := filepath.Rel(root, path)
	if err != nil || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return "", shortcut.Unavailable(reasonFileOutsideTarget)
	}
	return path, shortcut.Availability{}
}

// sameFinding says whether a and b are one finding across a re-scan: the line
// is not compared, the fix itself moves it.
func sameFinding(a, b scan.Finding) bool {
	return a.Source == b.Source &&
		remediation.RuleKey(a.ID) == remediation.RuleKey(b.ID) &&
		a.File == b.File && a.PkgName == b.PkgName && a.Version == b.Version &&
		instanceOf(a) == instanceOf(b)
}

// fixAction says how to show f.FixCommand: ("Run", cmd) for a real command,
// ("", instruction) for a sentence such as "Update pkg to 1.2", ("", "") when
// there is none.
func fixAction(f scan.Finding) (label, text string) {
	switch {
	case f.FixCommand == "":
		return "", ""
	case scan.IsFixInstruction(f):
		return "", f.FixCommand
	}
	return "Run", f.FixCommand
}
package security

import (
	"errors"
	"io/fs"
	"log"
	"path/filepath"
	"strings"

	tea "charm.land/bubbletea/v2"

	"github.com/anthnel/devdesk/internal/clipboard"
	"github.com/anthnel/devdesk/internal/scan"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
	uiviewer "github.com/anthnel/devdesk/internal/ui/viewer"
	"github.com/anthnel/devdesk/internal/viewer"
)

// The finding detail acts (DEVDESK-751). Its keys read the finding on screen
// (subjectFinding), never the table row behind it, and each one is decided by an
// availability the header and the handler share (Rule 130). DevDesk never runs
// the command under Run: Y copies it, and the user runs it.

// reasonNoCommand is why Y is greyed: the finding has nothing to copy.
const reasonNoCommand = "This finding has no command to run"

// writeClipboard is the clipboard write, a variable so a test can take it: the
// real one writes to the machine's clipboard. TestMain replaces it.
var writeClipboard = clipboard.WriteAll

// FixCommandCopiedMsg reports the clipboard write of the command under Run
// (Rule 109).
type FixCommandCopiedMsg struct {
	Command string
	Err     error
}

// subjectFinding is what a results or details action acts on: the finding on
// screen in the details state, the selected row in the results state. A re-scan
// puts the table back at the top, so the detail must never read the cursor.
func (m Model) subjectFinding() (scan.Finding, bool) {
	switch m.state {
	case StateDetails:
		if m.selectedFinding == nil {
			return scan.Finding{}, false
		}
		return *m.selectedFinding, true
	case StateResults:
		return m.findingsTable.Selected()
	}
	return scan.Finding{}, false
}

// canOpenFindingFile says whether enter can open the subject's file. It looks at
// the path only: whether the file exists is for the viewer to say.
func (m Model) canOpenFindingFile() shortcut.Availability {
	f, ok := m.subjectFinding()
	if !ok {
		return shortcut.Unavailable(reasonNoFinding)
	}
	_, a := findingFilePath(f, m.targetPath, m.targetOnDisk())
	return a
}

// canCopyFixCommand says whether Y has a command to copy.
func (m Model) canCopyFixCommand() shortcut.Availability {
	f, ok := m.subjectFinding()
	if !ok {
		return shortcut.Unavailable(reasonNoFinding)
	}
	if _, ok := runCommand(f); !ok {
		return shortcut.Unavailable(reasonNoCommand)
	}
	return shortcut.Availability{}
}

// FindingFileRefusedMsg reports that enter did not open the finding's file, and
// why (Rule 109).
type FindingFileRefusedMsg struct{ Reason string }

// openFindingFile asks the router to open the subject's file in the viewer. The
// Cmd follows the links of the path first (findingFilePath only reads it): a
// link that leaves the scanned directory is refused with a reason.
func (m Model) openFindingFile() (tea.Model, tea.Cmd) {
	if a := m.canOpenFindingFile(); !a.Enabled() {
		return m, m.footer.Warn(a.Reason)
	}
	f, _ := m.subjectFinding()
	path, _ := findingFilePath(f, m.targetPath, m.targetOnDisk())
	root := m.targetPath
	return m, func() tea.Msg {
		if !staysInside(root, path) {
			return FindingFileRefusedMsg{Reason: reasonFileLinkOutsideTarget}
		}
		return uiviewer.OpenRequestMsg{Source: viewer.NewFileSource(path)}
	}
}

// staysInside says whether path, with every link on it followed, is still under
// root, with every link on it followed too. A part of the path that does not
// exist is not a link: the existing part is resolved and the rest kept, so a
// missing file is still for the viewer to report. A path or a root that cannot be
// resolved for another reason (a permission) is not refused: the viewer cannot
// read it either.
func staysInside(root, path string) bool {
	realRoot, err := filepath.EvalSymlinks(filepath.Clean(root))
	if err != nil {
		return true
	}
	realPath, err := evalExisting(path)
	if err != nil {
		return true
	}
	rel, err := filepath.Rel(realRoot, realPath)
	return err == nil && rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator))
}

// evalExisting is filepath.EvalSymlinks on the longest existing prefix of path,
// followed by what does not exist.
func evalExisting(path string) (string, error) {
	resolved, err := filepath.EvalSymlinks(path)
	if err == nil || !errors.Is(err, fs.ErrNotExist) {
		return resolved, err
	}
	parent := filepath.Dir(path)
	if parent == path {
		return path, nil
	}
	resolved, err = evalExisting(parent)
	if err != nil {
		return "", err
	}
	return filepath.Join(resolved, filepath.Base(path)), nil
}

// copyFixCommand puts the command under Run on the clipboard, whole. It never
// runs it. The command is copied into the Cmd (Rule 110).
func (m Model) copyFixCommand() (tea.Model, tea.Cmd) {
	if a := m.canCopyFixCommand(); !a.Enabled() {
		return m, m.footer.Warn(a.Reason)
	}
	f, _ := m.subjectFinding()
	command, _ := runCommand(f)
	return m, func() tea.Msg {
		return FixCommandCopiedMsg{Command: command, Err: writeClipboard(command)}
	}
}

// handleFixCommandCopied reports the clipboard write: a notice on success, an
// error without its cause on failure (Rule 128).
func (m Model) handleFixCommandCopied(msg FixCommandCopiedMsg) (tea.Model, tea.Cmd) {
	if msg.Err != nil {
		log.Printf("ERROR [security] copy command: %v", msg.Err)
		return m, m.footer.Error("Failed to copy the command — check logs")
	}
	return m, m.footer.Info("Command copied to the clipboard")
}

// refreshDetails rebuilds the detail on the result just put on screen, or closes
// it when the finding is gone. It reports whether the detail is still open. The
// reason a detail closes is already in the footer: the verdict that brought the
// result says the rule is cleared, or still reported.
func (m *Model) refreshDetails() bool {
	if m.state != StateDetails {
		return false
	}
	if m.selectedFinding != nil && m.result != nil {
		for _, f := range m.result.Findings {
			if sameFinding(f, *m.selectedFinding) {
				m.selectedFinding = &f
				m.detailsViewport.SetContent(m.buildDetailsContent())
				return true
			}
		}
	}
	m.state = StateResults
	m.selectedFinding = nil
	return false
}

// verifyingStatus is the footer status while a fix waits on its re-scan: a state
// of the screen with the shared activity dot, derived on every frame and gone
// with the verdict. Only the target being verified says it.
func (m Model) verifyingStatus() (sharedcomponents.Status, bool) {
	if v := m.misconfigVerifying; v == nil || v.Target != m.targetPath {
		return sharedcomponents.Status{}, false
	}
	return sharedcomponents.Status{Text: "Re-scanning to confirm the fix...", Activity: true}, true
}
